'use strict';
(() => {
  const $ = (s) => document.querySelector(s);
  const config = window.EFE_CONFIG || {};
  const whatsappNumber = /^[1-9]\d{7,14}$/.test(config.whatsappNumber || '') ? config.whatsappNumber : '';
  const localDate = () => { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; };
  $('#date').min = localDate();
  $('#year').textContent = new Date().getFullYear();
  if('IntersectionObserver' in window){new IntersectionObserver(entries=>{document.body.classList.toggle('booking-visible',entries[0].isIntersecting);},{threshold:0}).observe($('#randevu'));}
  const menu = $('.menu-button');
  const closeMenu = () => { $('#navigation').classList.remove('open'); menu.setAttribute('aria-expanded', 'false'); menu.setAttribute('aria-label','Menüyü aç'); };
  menu.addEventListener('click', () => { const open = menu.getAttribute('aria-expanded') !== 'true'; $('#navigation').classList.toggle('open',open);menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Menüyü kapat':'Menüyü aç'); });
  document.querySelectorAll('#navigation a').forEach(a => a.addEventListener('click',closeMenu));
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu.getAttribute('aria-expanded')==='true'){closeMenu();menu.focus();}});
  const marqueeButton = $('.marquee-toggle');
  marqueeButton.addEventListener('click',()=>{const paused=$('.marquee').classList.toggle('paused');marqueeButton.setAttribute('aria-pressed',String(paused));marqueeButton.setAttribute('aria-label',paused?'Marka animasyonunu oynat':'Marka animasyonunu duraklat');marqueeButton.textContent=paused?'▷':'Ⅱ';});
  function openDialog(dialog){dialog.showModal();document.body.classList.add('modal-open');}
  document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>document.body.classList.remove('modal-open'));dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});});
  const works = [
    {title:'Periyodik bakım & kontrol',service:'Periyodik bakım',image:'assets/engine.webp',alt:'Eldivenli teknisyenin motor bölmesini kontrol ettiği temsili görsel',description:'Örnek bakım süreci: motor yağı ve filtrelerin değerlendirilmesi, sıvı seviyelerinin incelenmesi ve genel araç kontrolü. Uygulanacak işlemler aracın modeli, kilometresi ve bakım geçmişine göre belirlenir.'},
    {title:'Motor ve sistem kontrolü',service:'Arıza tespiti',image:'assets/garage.webp',alt:'Atölyede kaputu açık aracın yanında çalışan teknisyen; temsili görsel',description:'Örnek kontrol süreci: sürücünün gözlemlerinin dinlenmesi, gösterge uyarılarının incelenmesi ve gerekli sistem kontrolleri. Bulgular değerlendirilerek sonraki adım için bilgi verilir.'},
    {title:'Mekanik aksam incelemesi',service:'Mekanik onarım',image:'assets/engine.webp',alt:'Motor aksamını inceleyen teknisyen; temsili görsel',description:'Örnek inceleme süreci: mekanik aksamda ses, titreşim veya performans kaybı gibi belirtilerin değerlendirilmesi. Gerekli onarım, inceleme sonrasında araç sahibine açıklanır.'}
  ];
  function startBooking(service){if(service){$('#service').value=service;$('#service').removeAttribute('aria-invalid');$('#service-error').textContent='';}$('#randevu').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});$('#name').focus({preventScroll:true});}
  document.querySelectorAll('[data-service]').forEach(b=>b.addEventListener('click',()=>startBooking(b.dataset.service)));
  let workIndex=0;
  document.querySelectorAll('[data-work]').forEach(b=>b.addEventListener('click',()=>{workIndex=Number(b.dataset.work);const w=works[workIndex];$('#work-dialog-title').textContent=w.title;$('#work-dialog-description').textContent=w.description;$('#work-dialog-image').src=w.image;$('#work-dialog-image').alt=w.alt;openDialog($('#work-dialog'));}));
  $('#work-book').addEventListener('click',()=>{$('#work-dialog').close();startBooking(works[workIndex].service);});
  if(whatsappNumber){$('#booking-notice').hidden=true;$('#message-help').textContent='Henüz servise gönderilmedi. WhatsApp’ta açıp mesajınızı gönderin; randevu servis onayıyla kesinleşir.';}
  const contact = $('#contact-details');
  if(config.address||config.hours||whatsappNumber){contact.replaceChildren();if(whatsappNumber){const a=document.createElement('a');a.href=`https://wa.me/${whatsappNumber}`;a.className='text-action';a.target='_blank';a.rel='noopener noreferrer';a.textContent=`WhatsApp: ${config.phoneDisplay||'+'+whatsappNumber}`;contact.append(a);}for(const text of [config.address,config.hours])if(text){const p=document.createElement('p');p.textContent=text;contact.append(p);}}
  function validate(){const data={};let first=null;const today=localDate();$('#date').min=today;for(const id of ['name','vehicle','service','date']){const input=$('#'+id);data[id]=input.value.trim();let error='';if(!data[id])error={name:'Adınızı ve soyadınızı yazın.',vehicle:'Aracınızın marka ve modelini yazın.',service:'Lütfen bir hizmet seçin.',date:'Lütfen tercih ettiğiniz tarihi seçin.'}[id];else if(id==='name'&&data[id].length<2)error='Lütfen en az 2 karakter yazın.';else if(id==='date'&&(!/^\d{4}-\d{2}-\d{2}$/.test(data[id])||data[id]<today))error='Bugün veya ileri bir tarih seçin.';input.setAttribute('aria-invalid',String(!!error));$('#'+id+'-error').textContent=error;if(error&&!first)first=input;}if(first){first.focus();return null;}data.note=$('#note').value.trim();return data;}
  $('#booking-form').addEventListener('submit',e=>{e.preventDefault();const data=validate();if(!data)return;const date=new Intl.DateTimeFormat('tr-TR',{day:'numeric',month:'long',year:'numeric'}).format(new Date(data.date+'T12:00:00'));const message=`Merhaba Efe Oto Servis, randevu talebi oluşturmak istiyorum.\n\nAd Soyad: ${data.name}\nAraç: ${data.vehicle}\nHizmet: ${data.service}\nTercih Edilen Tarih: ${date}${data.note?'\nNot: '+data.note:''}\n\nMüsaitlik durumunuzu ve randevu için uygun saati paylaşabilir misiniz?`;$('#message-text').value=message;$('#copy-status').textContent='';$('#copy-message').textContent='Mesajı kopyala';const send=$('#whatsapp-send');send.hidden=!whatsappNumber;if(whatsappNumber)send.href=`https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`;else send.removeAttribute('href');openDialog($('#message-dialog'));});
  $('#copy-message').addEventListener('click',async()=>{const button=$('#copy-message');if(button.disabled)return;button.disabled=true;try{if(!navigator.clipboard?.writeText)throw new Error('Clipboard unavailable');await navigator.clipboard.writeText($('#message-text').value);$('#copy-status').textContent='Mesaj kopyalandı. Henüz servise gönderilmedi.';}catch{$('#message-text').focus();$('#message-text').select();$('#copy-status').textContent='Otomatik kopyalama kullanılamıyor. Seçili mesajı kopyalayıp WhatsApp’a yapıştırabilirsiniz.';}finally{button.disabled=false;}});
  $('#note').addEventListener('input',e=>{e.target.style.height='auto';e.target.style.height=Math.min(e.target.scrollHeight,240)+'px';});
  for(const id of ['name','vehicle','service','date']){$('#'+id).addEventListener('input',()=>{if($('#'+id).getAttribute('aria-invalid')==='true'){$('#'+id).removeAttribute('aria-invalid');$('#'+id+'-error').textContent='';}});}
  if(document.modelContext?.registerTool){const life=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'start_booking_request',title:'Randevu talebini başlat',description:'Seçilen hizmet için randevu formunu açar. Talep göndermez ve randevu oluşturmaz.',inputSchema:{type:'object',properties:{service:{type:'string',enum:[...$('#service').options].map(o=>o.value).filter(Boolean)}},required:['service'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>k!=='service')||![...$('#service').options].some(o=>o.value&&o.value===input.service))throw new Error('Geçerli bir hizmet seçin.');startBooking(input.service);return {status:'form_opened',service:$('#service').value,sent:false};}},{signal:life.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>life.abort(),{once:true});}
})();
